package bookstore

import "sort"

// discounts holds the total cost, in cents, of a group of 0-5 different
// books: no discount for one book, 5% for two, 10% for three, 20% for four
// and 25% for all five.
var discounts = [6]int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the total cost, in cents, of the books in the basket,
// grouped to give as big a discount as possible.
func Cost(books []int) int {
	counts := [5]int{}
	for _, b := range books {
		counts[b-1]++
	}
	sort.Slice(counts[:], func(i, j int) bool { return counts[i] > counts[j] })

	// Lay the books out in rows: row r holds one copy of every title of
	// which there are at least r. The rows are naturally the groups, and
	// because the counts are sorted, the row sizes are non-increasing:
	// g5 full sets of five, then the leftover rows of four, three, ...
	g5 := counts[4]
	g4 := counts[3] - counts[4]
	g3 := counts[2] - counts[3]
	g2 := counts[1] - counts[2]
	g1 := counts[0] - counts[1]

	cost := g5*discounts[5] + g4*discounts[4] + g3*discounts[3] + g2*discounts[2] + g1*discounts[1]

	// A group of five and a group of three cost 5160 together, but the same
	// eight books can be split into two groups of four for 5120, saving 40
	// per pair. (Two of each of three titles plus one of the remaining two
	// always partitions into two sets of four.)
	if g5 < g3 {
		cost -= g5 * 40
	} else {
		cost -= g3 * 40
	}
	return cost
}

