package main

import (
	"fmt"
	"os"
)

var discounts = [6]int{0, 800, 1520, 2160, 2560, 3000}

// fast: the implemented solution (row decomposition + (5,3)->(4,4) fix)
func fast(counts [5]int) int {
	c := [5]int{}
	// sort descending
	for i := 0; i < 5; i++ {
		for j := i + 1; j < 5; j++ {
			if c[j] > c[i] {
				c[i], c[j] = c[j], c[i]
			}
		}
	}
	copy(c, counts)
	g5 := c[4]
	g4 := c[3] - c[4]
	g3 := c[2] - c[3]
	g2 := c[1] - c[2]
	g1 := c[0] - c[1]
	cost := g5*discounts[5] + g4*discounts[4] + g3*discounts[3] + g2*discounts[2] + g1*discounts[1]
	if g5 < g3 {
		cost -= g5 * 40
	} else {
		cost -= g3 * 40
	}
	return cost
}

// exact: memoized DP over the labeled count vector; a move picks any
// non-empty subset of titles with remaining copies (one group).
var memo = map[[5]int]int{}

func exact(c [5]int) int {
	if v, ok := memo[c]; ok {
		return v
	}
	best := 0
	for mask := 1; mask < 32; mask++ {
		size := 0
		ok := true
		for t := 0; t < 5; t++ {
			if mask&(1<<t) != 0 {
				if c[t] == 0 {
					ok = false
					break
				}
				size++
			}
		}
		if !ok {
			continue
		}
		n := c
		for t := 0; t < 5; t++ {
			if mask&(1<<t) != 0 {
				n[t]--
			}
		}
		if v := discounts[size] + exact(n); v > best {
			best = v
		}
	}
	memo[c] = best
	return best
}

func main() {
	maxTotal := 14
	bad := 0
	total := 0
	var worst [5]int
	worstDiff := 0
	// enumerate all count vectors with sum <= maxTotal
	var rec func(c [5]int, rem int)
	rec = func(c [5]int, rem int) {
		total++
		f, e := fast(c), exact(c)
		if f != e {
			bad++
			diff := f - e
			if diff > worstDiff {
				worstDiff = diff
				worst = c
			}
			if bad < 20 {
				fmt.Printf("MISMATCH counts=%v fast=%d exact=%d\n", c, f, e)
			}
		}
		for t := 0; t < 5; t++ {
			if c[t] < maxTotal {
				c[t]++
				rec(c, rem)
				c[t]--
			}
		}
	}
	rec([5]int{}, maxTotal)
	fmt.Printf("checked %d count vectors, %d mismatches (worst diff %d at %v)\n", total, bad, worstDiff, worst)
	if bad > 0 {
		os.Exit(1)
	}
}

